import { CalendarDay } from '../types/configs.types';
import { DAYS_IN_MONTH, STATUS_BADGE } from '../data/configs.data';
import PickStatus from './PickStatus';

export default function BuildStaticMonth(): CalendarDay[] {
    const cells: CalendarDay[] = [];
    // March 2025 starts Saturday → no leading blanks
    for (let d = 1; d <= DAYS_IN_MONTH; d++) {
        const rest = PickStatus(d, true);
        cells.push({ day: d, isCurrentMonth: true, ...rest });
    }
    // Trailing days from next month (grey "1" cells like design)
    const trailing = 7 - (cells.length % 7);
    if (trailing < 7) {
        for (let i = 0; i < trailing; i++) {
            cells.push({
                day: i + 1,
                isCurrentMonth: false,
                status: 'inactive',
                line1: '',
                line2: '',
                badgeLabel: STATUS_BADGE.inactive.label,
            });
        }
    }
    return cells;
}