import SettingsIcon from '@/components/icons/statistics/SettingIcon';
import UserIcon from '@/components/icons/statistics/UserIcon';
import CalendarIcon from '@/components/icons/statistics/CalendarIcon';
import CarIcon from '@/components/icons/statistics/CarIcon';
import { Card } from '@/types/statistics';
import ShopIcon from '@/components/icons/ShopIcon';
import UserIconH from '@/components/icons/statistics/UserIconH';
import PeopleIcon from '@/components/icons/PeopleIcon';
import GroupIcon from '@/components/icons/user/GroupIcon';
import UserRemoveIcon from '@/components/icons/UserRemoveIcon';
import TwoUsersIcon from '@/components/icons/user/TwoUsersIcon';
import MinusUserIcon from '@/components/icons/user/MinusUserIcon';
import FileIcon from '@/components/icons/sidebar/FileIcon';
import { useEffect, useState } from 'react';
import { endpoints } from '@/lib/axios/axios-global';
import { apiGet } from '@/lib/axios/axios-utils';
import { HomeStats } from '@/types/dashboard.types';
import StatisticsCards from './StatisticsCards';

export default function StatisticsCardsComponent() {
    const [data, setData] = useState<HomeStats | null>(null);

    useEffect(() => {
        const fetchStats = async () => {
            try {
                const res = await apiGet({
                    endpoint: endpoints.dashboard.analytics,
                });
                setData(res.data.data);
            } catch {
                setData(null);
            }
        };
        fetchStats();
    }, []);

    const getStat = (key: string) => data?.find((s) => s.key === key);

    const cards: Card[] = [
        {
            text: 'اجمالي السيارات',
            icon: <CalendarIcon />,
            num: getStat('total_vehicles')?.value,
            percent: getStat('total_vehicles')?.change_percent ?? 0,
            to: '/invoicing',
        },
        {
            text: 'متاح',
            icon: <UserIcon />,
            num: getStat('available')?.value,
            percent: getStat('available')?.change_percent ?? -1,
            to: '/cars',
        },
        {
            text: 'تأجير',
            icon: <SettingsIcon />,
            num: getStat('rent')?.value,
            percent: getStat('rent')?.change_percent ?? 8,
            to: '/cars/booking',
        },
        {
            text: 'صيانه',
            icon: <CarIcon />,
            num: getStat('maintenance')?.value,
            percent: getStat('maintenance')?.change_percent ?? 10,
            to: '/maintenance',
        },
        {
            text: 'إجمالي العاملين',
            num: getStat('total_employees')?.value,
            percent: getStat('total_employees')?.change_percent ?? 12,
            icon: <GroupIcon />,
            to: '/human-resources/employees',
        },
        {
            text: 'متوسط التقيم',
            num: getStat('average_rating')?.value,
            percent: getStat('average_rating')?.change_percent ?? 0,
            icon: <UserRemoveIcon />,
            to: '/human-resources/employees',
        },
        {
            text: 'العاملين دوام كلي',
            num: getStat('full_time_employees')?.value,
            percent: getStat('full_time_employees')?.change_percent ?? -0.3,
            icon: <TwoUsersIcon />,
            to: '/human-resources/employees',
        },
        {
            text: 'العاملين دوام جزئي',
            num: getStat('part_time_employees')?.value,
            percent: getStat('part_time_employees')?.change_percent ?? -0.3,
            icon: <MinusUserIcon />,
            to: '/human-resources/employees',
        },
        {
            text: 'اجمالي عدد العملاء',
            icon: <UserIconH />,
            num: getStat('total_customers')?.value,
            percent: getStat('total_customers')?.change_percent ?? 0,
            to: '/customer-relations',
        },
        {
            text: 'عدد الفروع',
            icon: <ShopIcon />,
            num: getStat('branches_count')?.value,
            percent: getStat('branches_count')?.change_percent ?? 0,
            to: '/branches/list',
        },
        {
            text: 'إجمالي العقود',
            icon: <PeopleIcon />,
            num: getStat('total_contracts')?.value,
            percent: getStat('total_contracts')?.change_percent ?? 12,
            to: '/cars/contract-archive',
        },
        {
            text: 'البرامج',
            icon: <FileIcon className="w-8 h-8 text-primery-blue-900" />,
            to: '/programs',
        },
    ];

    return <StatisticsCards cards={cards} />;
}
