import { useState } from 'react';
import { AttendanceCalendarPagination } from './AttendanceCalendarPagination';
import { WEEKDAYS_AR } from '../data/configs.data';
import DayCell from './DayCell';
import BuildStaticMonth from './buildStaticMonth';

const STATIC_CELLS = BuildStaticMonth();

const TOTAL_ITEMS = 97;
const PAGE_SIZE = 10;

const AttendanceDeparture = () => {
  const [page, setPage] = useState(1);

  return (
    <section className="mt-10 font-cairo" dir="rtl">
      <div className="mb-4 rounded-t-md bg-slate-100/90 px-2 py-3">
        <div className="grid grid-cols-7 gap-2 text-center text-sm font-medium text-neutral-700">
          {WEEKDAYS_AR.map((name) => (
            <div key={name} className="px-1">
              {name}
            </div>
          ))}
        </div>
      </div>

      <div className="grid grid-cols-7 gap-2 border border-[#e0e0e0] border-t-0 bg-neutral-50/30 p-2">
        {STATIC_CELLS.map((cell, idx) => (
          <DayCell key={`${cell.day}-${cell.isCurrentMonth}-${idx}`} cell={cell} />
        ))}
      </div>

      <AttendanceCalendarPagination
        page={page}
        onPageChange={setPage}
        totalItems={TOTAL_ITEMS}
        pageSize={PAGE_SIZE}
      />
    </section>
  );
};

export default AttendanceDeparture;
