import React, { useMemo } from 'react';
import { cn } from '@/lib/utils';

export type AttendanceCalendarPaginationProps = {
    page: number;
    onPageChange: (page: number) => void;
    totalItems: number;
    pageSize: number;
    className?: string;
};

export function AttendanceCalendarPagination({
    page,
    onPageChange,
    totalItems,
    pageSize,
    className,
}: AttendanceCalendarPaginationProps) {
    const totalPages = Math.max(1, Math.ceil(totalItems / pageSize));
    const from = (page - 1) * pageSize + 1;
    const to = Math.min(page * pageSize, totalItems);

    const pageNumbers = useMemo(() => {
        const pages: (number | 'ellipsis')[] = [];
        const show = [10, 9, 8, 'ellipsis', 3, 2, 1] as const;
        for (const p of show) {
            if (p === 'ellipsis') pages.push('ellipsis');
            else if (p <= totalPages) pages.push(p);
        }
        return pages;
    }, [totalPages]);

    return (
        <div
            className={cn(
                'mt-4 flex flex-wrap items-center justify-between gap-3 border-t border-[#e0e0e0] pt-4 text-sm text-neutral-600',
                className,
            )}
        >
            <p>
                عرض {from} الى {to} من {totalItems}
            </p>
            <div className="flex flex-wrap items-center gap-1">
                <button
                    type="button"
                    className="flex h-9 min-w-9 items-center justify-center rounded border border-neutral-300 bg-white px-2 text-neutral-700 hover:bg-neutral-50 disabled:opacity-40"
                    disabled={page <= 1}
                    onClick={() => onPageChange(Math.max(1, page - 1))}
                    aria-label="الصفحة السابقة"
                >
                    ‹
                </button>
                {pageNumbers.map((p, i) =>
                    p === 'ellipsis' ? (
                        <span key={`e-${i}`} className="px-1 text-neutral-500">
                            ...
                        </span>
                    ) : (
                        <button
                            key={p}
                            type="button"
                            onClick={() => onPageChange(p)}
                            className={cn(
                                'flex h-9 min-w-9 items-center justify-center rounded border px-2 text-sm',
                                page === p
                                    ? 'border-blue-600 text-blue-600'
                                    : 'border-neutral-300 bg-white text-neutral-700 hover:bg-neutral-50',
                            )}
                        >
                            {p}
                        </button>
                    ),
                )}
                <button
                    type="button"
                    className="flex h-9 min-w-9 items-center justify-center rounded border border-neutral-300 bg-white px-2 text-neutral-700 hover:bg-neutral-50 disabled:opacity-40"
                    disabled={page >= totalPages}
                    onClick={() => onPageChange(Math.min(totalPages, page + 1))}
                    aria-label="الصفحة التالية"
                >
                    ›
                </button>
            </div>
        </div>
    );
}
