import { CalendarDay } from '../types/configs.types';
import { STATUS_BADGE } from '../data/configs.data';


export default function PickStatus(day: number, isCurrentMonth: boolean): Omit<CalendarDay, 'day' | 'isCurrentMonth'> {
    if (!isCurrentMonth) {
        return {
            status: 'inactive',
            line1: '',
            line2: '',
            badgeLabel: STATUS_BADGE.inactive.label,
        };
    }
    const cycle = day % 7;
    if (cycle === 0 || cycle === 5) {
        return {
            status: 'attendance',
            line1: 'وقت الدخول: 8:00 AM',
            line2: 'وقت الخروج: 5:00 PM',
            badgeLabel: STATUS_BADGE.attendance.label,
        };
    }
    if (cycle === 1 || cycle === 6) {
        return {
            status: 'absence',
            line1: 'سبب الغياب: ايام العطله',
            line2: 'الموافق: 2024/5/5',
            badgeLabel: STATUS_BADGE.absence.label,
        };
    }
    if (cycle === 2) {
        return {
            status: 'vacation',
            line1: 'نوع الاجازه: ايام العطله',
            line2: 'نظام الاجازه السعودي',
            badgeLabel: STATUS_BADGE.vacation.label,
        };
    }
    return {
        status: 'inactive',
        line1: '',
        line2: '',
        badgeLabel: STATUS_BADGE.inactive.label,
    };
}